-- ============================================
-- USUARIOS: usuarios del sistema (login con DNI + clave bcrypt; EMAIL solo de contacto)
-- INTENTOS_FALLIDOS / BLOQUEADO_HASTA: bloqueo temporal tras varios intentos fallidos
-- ============================================
CREATE TABLE IF NOT EXISTS "USUARIOS" (
    "ID_USUARIO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_USUARIOS" PRIMARY KEY,
    "NOMBRES" VARCHAR(100) NOT NULL,
    "APELLIDOS" VARCHAR(150) NULL,
    "EMAIL" VARCHAR(150) NULL,
    "DNI" CHAR(8) NOT NULL CONSTRAINT "UQ_USUARIOS_DNI" UNIQUE
        CONSTRAINT "CHK_USUARIOS_DNI" CHECK ("DNI" ~ '^[0-9]{8}$'),
    "PASSWORD_HASH" VARCHAR(255) NULL,
    "REQUIERE_CAMBIO_PASSWORD" BOOLEAN NOT NULL DEFAULT TRUE,
    "INTENTOS_FALLIDOS" INT NOT NULL DEFAULT 0,
    "BLOQUEADO_HASTA" TIMESTAMPTZ NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    "FECHA_CREACION" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "FECHA_EDICION" TIMESTAMPTZ NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_USUARIOS_EMAIL" ON "USUARIOS" ("EMAIL") WHERE "EMAIL" IS NOT NULL;
